		UPDATE ICOMBYIT_ADD A                        
           SET A.STATUS='X',                        
                A.COM_CODE=BUYER,                    
                A.QUOTATION_NO=#{QUOTATION_NO},
                A.QUOTATION_SEQ=LPAD(#{QUOTATION_SEQ}, 6, '0'),
                A.REVISION=1                        
         WHERE A.BUYER = #{st_buyer_code}
                    AND A.BUYER_ITEM_NO=#{BUYER_ITEM_NO}
                    AND A.SEQ=#{SEQ}

