/*updateCancleKepRcdt*/
UPDATE KEP_RCDT A
SET RC_TYPE = 'S'
, CHANGE_DATE = SYSDATE
WHERE (RC_NO,RC_SEQ,REVISION) IN (
 SELECT QUOTATION_NO, QUOTATION_SEQ, REVISION
 FROM KEPMGPDT
 WHERE BUYER = #{KEY_2}
 AND PM_NO = #{KEY_1} 
)
